import { useCallback, useEffect, useState } from 'react'
import {
    DEFAULT_CARD_TYPES,
    DEFAULT_STATES,
    type BranchReference,
    type CardDraft,
    type ReleaseBranchCandidate,
} from '../../../data/data_types'
